import android.telephony.TelephonyManager;

public class RemoveGladiatorFromPhoneNumber {

    public static void removeGladiatorFromPhoneNumber(String number) {
        TelephonyManager telephonyManager = (TelephonyManager) getSystemService(Context.TELEPHONY_SERVICE);

        // Get the number of the calling device
        String callingDevice = telephonyManager.getLine1Number();

        // Check if the calling device is the gladiator
